function Mark() { return <img className="eil-approved-mark" src={`${BASE}eil-favicon.png`} alt="" aria-hidden="true" /> }
function Status({ children }: { children: string }) { return <span className="eil-status">{children}</span> }
function Disclosure({ summary, children }: { summary: string; children: ReactElement | ReactElement[] }) {
  return <details className="eil-disclosure"><summary>{summary}</summary><div className="eil-disclosure-body">{children}</div></details>
}

export function InstitutionalSite({ route, content }: { route: InstitutionalRoute; content: SiteContent }) {
  const { lang, setLang } = useLang()
  const { theme, cycle } = useTheme()
  const de = lang === 'de'
  const tx = (german: string, english: string) => de ? german : english
  const navigation: Array<[InstitutionalRoute, string, string]> = [
    ['lab', 'Lab', 'Lab'], ['research', 'Forschung', 'Research'], ['methods', 'Methoden', 'Methods'],
    ['systems', 'Systeme', 'Systems'], ['publications', 'Publikationen', 'Publications'],
    ['observatory', 'Observatory', 'Observatory'], ['applied-research', 'Applied Research', 'Applied Research'],
  ]

  useEffect(() => {
    const names: Record<InstitutionalRoute, string> = { home: '', lab: 'Lab', research: tx('Forschung', 'Research'), methods: tx('Methoden', 'Methods'), systems: tx('Systeme', 'Systems'), publications: tx('Publikationen', 'Publications'), observatory: 'Observatory', notes: 'Research Notes', 'applied-research': 'Applied Research' }
    document.title = `${names[route] ? `${names[route]} · ` : ''}Emergent Interaction Lab`
  }, [route, lang])

  const Header = () => <header className="eil-header">
    <a className="eil-brand" href={href('home')} aria-label="Emergent Interaction Lab — Home"><Mark /></a>
    <nav className="eil-nav" aria-label={tx('Hauptnavigation', 'Primary navigation')}>
      {navigation.map(([id, d, e]) => <a key={id} href={href(id)} className={route === id ? 'active' : ''}>{tx(d, e)}</a>)}
    </nav>
    <div className="eil-tools"><button onClick={() => setLang(de ? 'en' : 'de')}>{lang.toUpperCase()}</button><button onClick={cycle} aria-label={tx('Farbschema wechseln', 'Change color scheme')}>{theme === 'dark' ? '◐' : theme === 'light' ? '○' : '◉'}</button><a className="eil-contact-link" href={`${href('home')}#contact`}>{tx('Kontakt', 'Contact')}</a><details className="eil-mobile-menu"><summary aria-label={tx('Menü öffnen', 'Open menu')}>☰</summary><nav>{navigation.map(([id,d,e])=><a key={id} href={href(id)}>{tx(d,e)}</a>)}<a href={href('notes')}>Research Notes</a></nav></details></div>
  </header>

  const Footer = () => <footer className="eil-footer">
    <div><Mark /><strong>Emergent Interaction Lab</strong><p>{tx('Unabhängiges, founder-led Forschungslabor.', 'Independent founder-led research lab.')}</p></div>
    <div className="eil-footer-links"><a href={href('notes')}>Research Notes</a><a href="https://github.com/rfi-irfos/emergent-interaction-lab">GitHub</a><a href={`${href('home')}#p/datenschutz`}>Datenschutz</a><a href={`${href('home')}#p/impressum`}>Impressum</a></div>
    <p className="eil-doctrine">Human rights are not subject to negotiation.<small>{tx('Emergent Interaction Lab · unabhängige Forschungsinstitution', 'Emergent Interaction Lab · independent research institution')}</small></p>
  </footer>

  const PageHero = ({ eyebrow, title, body }: { eyebrow: string; title: string; body: string }) => <section className="eil-page-hero"><Status>{eyebrow}</Status><h1>{title}</h1><p>{body}</p></section>

  const Domains = () => <section className="eil-section"><div className="eil-section-head"><Status>RESEARCH DOMAINS</Status><h2>{tx('Forschungsfelder', 'Research domains')}</h2><p>{tx('Human–AI Interaction ist eines davon, nicht die Definition des gesamten Labs.', 'Human–AI interaction is one of them, not the definition of the entire Lab.')}</p></div><div className="eil-domain-grid">{domains.map(([n,d,e,dd,ee]) => <article key={n} className="eil-card"><span className="eil-index">{n}</span><h3>{tx(d,e)}</h3><Disclosure summary={tx('Forschungsfrage','Research question')}><p>{tx(dd,ee)}</p></Disclosure></article>)}</div></section>

  const HomeDomains = () => <section className="eil-section eil-home-domains"><div className="eil-section-head"><Status>SEVEN CONNECTED RESEARCH DOMAINS</Status><h2>{tx('Forschungsbreite, ohne das Lab auf ein Feld zu reduzieren.', 'Research breadth without reducing the Lab to one field.')}</h2></div><div className="eil-domain-chips">{domains.map(([,d,e])=><span key={e}>{tx(d,e)}</span>)}</div><a className="eil-text-link" href={href('research')}>{tx('Forschungslandschaft ansehen','Explore Research')} →</a></section>

  const ObjectsAndPerspectives = ({ compact = false }: { compact?: boolean } = {}) => <div className={compact ? 'eil-home-taxonomy' : undefined}><section className="eil-section eil-object-section"><div className="eil-section-head"><Status>OBJECTS OF STUDY</Status><h2>{tx('Was untersucht wird', 'What we study')}</h2><p>{tx('Die Forschungsobjekte sind konkrete Systeme und Evidenzumgebungen — nicht austauschbare Servicekategorien.', 'Research objects are concrete systems and evidence environments—not interchangeable service categories.')}</p></div><div className="eil-domain-grid">{objectsOfStudy.map(([name,d,e]) => <article key={name} className="eil-card"><h3>{name}</h3>{compact?<p>{tx(d,e)}</p>:<Disclosure summary={tx('Definition','Definition')}><p>{tx(d,e)}</p></Disclosure>}</article>)}</div></section><section className="eil-section eil-perspective-section"><div className="eil-section-head"><Status>ANALYTICAL PERSPECTIVES</Status><h2>{tx('Ein System, mehrere Perspektiven', 'One system, multiple perspectives')}</h2><p>{tx('Nicht jede Untersuchung verwendet jede Linse gleich stark. Die Kombination folgt Forschungsfrage, System und verfügbarer Evidenz.', 'Not every investigation uses every lens equally. The combination follows the research question, system and available evidence.')}</p></div><div className="eil-domain-grid">{perspectives.map(([name,d,e]) => <article key={name} className="eil-card"><span className="eil-index">{name}</span>{compact?<p>{tx(d,e)}</p>:<Disclosure summary={tx('Analytische Frage','Analytical question')}><p>{tx(d,e)}</p></Disclosure>}</article>)}</div></section></div>

  const EvidenceModel = () => <section className="eil-evidence"><div className="eil-section-head"><Status>EVIDENCE ARCHITECTURE</Status><h2>{tx('Was wissen wir – und wie?', 'What do we know—and how?')}</h2><p>{tx('Epistemischer Status, Provenienz und Widerspruch bleiben getrennte Dimensionen.', 'Epistemic status, provenance and contradiction remain distinct dimensions.')}</p></div><div className="eil-evidence-grid">{evidenceStates.map(([state,d,e])=><article key={state}><Status>{state}</Status><Disclosure summary={tx('Definition','Definition')}><p>{tx(d,e)}</p></Disclosure></article>)}</div><div className="eil-evidence-axes"><article><Status>PROVENANCE</Status><h3>{tx('Woher kommt die Information?', 'Where did the information come from?')}</h3><Disclosure summary={tx('Felder anzeigen','Show fields')}><p>{tx('Quelle · Zeitpunkt · Kontext · Transformations- oder Ableitungspfad', 'Source · time · context · transformation or derivation path')}</p></Disclosure></article><article><Status>CONTRADICTION</Status><h3>{tx('Was fordert das Modell heraus?', 'What challenges the model?')}</h3><Disclosure summary={tx('Abgrenzung','Boundary')}><p>{tx('Widerspruch wird separat markiert: bekannte Herkunft bedeutet nicht automatisch widerspruchsfreie Evidenz.', 'Contradiction is marked separately: known provenance does not imply uncontested evidence.')}</p></Disclosure></article></div></section>

  const EvidenceBridge = () => <section className="eil-callout eil-evidence-bridge"><Status>EVIDENCE ARCHITECTURE</Status><h2>{tx('Claims bleiben mit Quelle, Evidenzstatus und Unsicherheit verbunden.', 'Claims remain linked to source, evidence status and uncertainty.')}</h2><a className="eil-text-link" href={href('methods')}>{tx('Evidence Architecture ansehen', 'Explore Evidence Architecture')} →</a></section>

  const AgentEnvironment = () => <section className="eil-callout eil-agent-environment"><Status>COMPUTATIONAL RESEARCH ENVIRONMENT</Status><h2>{tx(`${institutionalFacts.specializedResearchAgentCrates} spezialisierte Forschungsagenten.`, `${institutionalFacts.specializedResearchAgentCrates} specialized research agents.`)}</h2><p>{tx('Die bestätigte Zählsemantik ist: individuell geschriebene spezialisierte Rust-Crates, die über einen Orchestrator bedarfsgerecht aufgerufen werden.', 'The confirmed count semantics are individually authored specialist Rust crates invoked through an orchestrator as needed.')}</p><small>{tx(`Beispiele: DevOps, Red Team, Legal, Finance, HR, Evidence Analysis und Behavioral Analysis. Die Agenten sind keine ${institutionalFacts.specializedResearchAgentCrates} Stimmen über dieselbe Frage; Konsens ersetzt keine Evidenz.`, `Examples include DevOps, Red Team, Legal, Finance, HR, Evidence Analysis and Behavioral Analysis. The agents are not ${institutionalFacts.specializedResearchAgentCrates} votes on one question; agreement does not replace evidence.`)}</small></section>

  const ResearchEnvironmentOverview = () => <section className="eil-section eil-environment-overview"><div className="eil-section-head"><Status>RESEARCH ENVIRONMENT</Status><h2>{tx('Vier verbundene Schichten – keine vier Produkte.', 'Four connected layers—not four products.')}</h2><p>{tx('Die Umgebung verbindet abgegrenzte analytische Rollen, persistente Evidenzbeziehungen, Zustandsdarstellung und longitudinale Beobachtung entsprechend der Forschungsfrage.', 'The environment connects bounded analytical roles, persistent evidence relationships, state representation and longitudinal observation according to the research question.')}</p></div><div className="eil-environment-grid"><article><h3>Specialized Research Agents</h3><p>{tx('Explizite Rollen, Inputs, Outputs und Attribution für wiederholbare analytische Operationen.','Explicit roles, inputs, outputs and attribution for repeatable analytical operations.')}</p></article><article><h3>Research Knowledge Graph</h3><p>{tx('Entitäten, Claims, Evidenz, Quellen, Ereignisse und Beziehungen bleiben nachvollziehbar verbunden.','Entities, claims, evidence, sources, events and relationships remain traceably connected.')}</p></article><article><h3>EIL World Model</h3><p>{tx('Beobachtete Zustände, mögliche Übergänge, Alternativen und Unsicherheit werden strukturiert repräsentiert.','Observed states, possible transitions, alternatives and uncertainty are represented structurally.')}</p></article><article><h3>Observatory</h3><p>{tx('Drift, Rollenstabilität, Interaktionsdynamik, Zustandswechsel, Widersprüche und Kontext werden longitudinal beobachtet.','Drift, role stability, interaction dynamics, state transitions, contradictions and context are observed longitudinally.')}</p></article></div></section>

  const ResearchMap = () => <section className="eil-section"><div className="eil-section-head"><Status>SELECTED RESEARCH RELATIONSHIPS</Status><h2>{tx('Konkrete Verbindungen im Forschungsraum', 'Concrete relationships across the research space')}</h2><p>{tx('Ausgewählte Beispiele zeigen many-to-many-Beziehungen – keine Pflichtpipeline.', 'Selected examples show many-to-many relationships—not a mandatory pipeline.')}</p></div><div className="eil-research-map eil-research-map--examples">{[
    ['Complex Systems & Emergence','Longitudinal Analysis','Observatory','Research Notes · Models'],
    ['Behavioral Intelligence','Behavioral Analysis','Observatory','Behavioral Landscape'],
    ['System Reconstruction','Reconstructive Analysis','Knowledge Graph · EIL World Model','Reconstruction Report'],
    ['System Integrity','Contradiction Mapping','Call Laura · Evidence Architecture','Integrity Findings'],
  ].map(row=><article key={row[0]}>{row.map((cell,i)=><div key={cell}><small>{['DOMAIN','METHOD / PERSPECTIVE','SYSTEM / INSTRUMENT','OUTPUT'][i]}</small><strong>{cell}</strong>{i<3&&<span>↔</span>}</div>)}</article>)}</div></section>

  const Home = () => <>
    <section className="eil-home-hero"><div><Status>{tx('UNABHÄNGIGES FORSCHUNGSLABOR','INDEPENDENT RESEARCH LAB')}</Status><img className="eil-hero-wordmark-image" src={`${BASE}eil-hero-wordmark-full-alpha.png`} alt="Emergent Interaction Lab" /><h1 className="eil-hero-statement">{tx('EIL untersucht, wie menschliche, computationale und sozio-technische Systeme sich verhalten, interagieren, verändern und beobachtbar werden.', 'EIL investigates how human, computational and socio-technical systems behave, interact, change and become observable.')}</h1><div className="eil-actions"><a href={href('research')}>{tx('Forschung ansehen', 'Explore research')} →</a><a href={href('methods')}>{tx('Methoden', 'Methods')}</a></div></div></section>
    <section className="eil-thesis"><Status>{tx('WARUM DIESE FORSCHUNG EXISTIERT','WHY THIS RESEARCH EXISTS')}</Status><h2>{tx('Ein System ist mehr als seine formale Beschreibung.', 'A system is more than its formal description.')}</h2><p>{tx('Software, KI, Organisationen und andere komplexe Systeme zeigen sich auch durch Verhalten, Interaktion, Abweichung, Beziehungen und Veränderung über Zeit. EIL untersucht diese Ebenen gemeinsam, ohne Beobachtung mit Erklärung gleichzusetzen.', 'Software, AI, organizations and other complex systems also reveal themselves through behavior, interaction, deviation, relationships and change over time. EIL studies these layers together without treating observation as explanation.')}</p></section>
    <ObjectsAndPerspectives compact />
    <HomeDomains />
    <section className="eil-callout eil-research-environment"><Status>RESEARCH ENVIRONMENT</Status><h2>{tx('Infrastruktur aus Forschungsanforderungen.', 'Infrastructure shaped by research requirements.')}</h2><p>{tx('Hunderte spezialisierte Forschungsagenten übernehmen abgegrenzte Operationen; der Research Knowledge Graph verbindet Objekte, Quellen und Beziehungen; das EIL World Model hält Zustände, Veränderungen und Unsicherheit strukturiert; das Observatory beobachtet diese Dynamik über Zeit.', 'Hundreds of specialized research agents perform bounded operations; the Research Knowledge Graph connects objects, sources and relationships; the EIL World Model represents states, changes and uncertainty; the Observatory follows these dynamics over time.')}</p><Disclosure summary={tx('Technische Umsetzung und Claim-Grenze','Technical implementation and claim boundary')}><p>{tx(`Die Umgebung umfasst derzeit ${institutionalFacts.specializedResearchAgentCrates} individuell geschriebene spezialisierte Rust-Crates, die über einen Orchestrator bedarfsgerecht aufgerufen werden. Sie sind keine ${institutionalFacts.specializedResearchAgentCrates} Stimmen über dieselbe Frage; Konsens ersetzt keine Evidenz.`, `The environment currently comprises ${institutionalFacts.specializedResearchAgentCrates} individually authored specialist Rust crates invoked through an orchestrator as needed. They are not ${institutionalFacts.specializedResearchAgentCrates} votes on one question; agreement does not replace evidence.`)}</p></Disclosure></section>
    <EvidenceBridge />
    <section className="eil-output-strip"><Status>RESEARCH OUTPUTS</Status><h2>{tx('Forschung endet nicht beim Paper.', 'Research does not end with a paper.')}</h2><div>{researchOutputs.map(x=><span key={x}>{x}</span>)}</div></section><section className="eil-callout eil-applied-bridge"><Status>APPLIED RESEARCH BRIDGE</Status><h2>{tx('Ausgewählte Fähigkeiten, klar begrenzte Untersuchungen.', 'Selected capabilities, bounded investigations.')}</h2><p>{tx('Ausgewählte EIL-Capabilities können auf externe Systeme und komplexe Fälle angewendet werden – mit definierter Forschungsfrage, Systemgrenze, Evidenzbasis und Ergebnisartefakt.', 'Selected EIL capabilities can be applied to external systems and complex cases—with a defined research question, system boundary, evidence base and output artifact.')}</p><a className="eil-text-link" href={href('applied-research')}>{tx('Applied Research ansehen', 'Explore applied research')} →</a></section>
    <section className="eil-contact" id="contact"><div><Status>CONTACT</Status><h2>{tx('Mit dem Lab arbeiten', 'Work with the Lab')}</h2><p>{tx('Forschungskooperation, methodische Rückfrage oder Applied-Research-Anfrage.', 'Research collaboration, methodology question or applied-research enquiry.')}</p></div><form action="https://api.web3forms.com/submit" method="POST" className="eil-contact-form"><input type="hidden" name="access_key" value={import.meta.env.VITE_WEB3FORMS_KEY ?? ''}/><input type="hidden" name="subject" value="Emergent Interaction Lab enquiry"/><input name="name" required placeholder={tx('Name', 'Name')}/><input name="email" type="email" required placeholder={tx('E-Mail', 'Email')}/><textarea name="message" required rows={4} placeholder={tx('Worum geht es?', 'What would you like to discuss?')}/><button type="submit">{tx('Anfrage senden', 'Send enquiry')} →</button></form></section>
  </>

  const LabConvergence = () => <section className="eil-section eil-lab-convergence"><div className="eil-section-head"><Status>{tx('WARUM DIESE FELDER HIER ZUSAMMENKOMMEN', 'WHY THESE FIELDS MEET HERE')}</Status><h2>{tx('Ein System, mehrere analytische Anforderungen.', 'One system, multiple analytical requirements.')}</h2><p>{tx('Sechs Perspektiven beantworten unterschiedliche Fragen am selben Untersuchungsobjekt.', 'Six perspectives answer different questions about the same research object.')}</p></div><div className="eil-role-grid">{[
    ['HMI','Welche Zustände werden sichtbar, verständlich und handlungsrelevant – und was geht an Interfaces verloren?','Which states become visible, understandable and actionable—and what is lost at interfaces?'],
    ['Behavioral Analysis','Welche beobachtbaren Muster bleiben stabil und welche verändern sich?','Which observable patterns remain stable and which change?'],
    ['Agentic Systems','Wie entstehen Rollen, Koordination, gemeinsamer Zustand und Drift?','How do roles, coordination, shared state and drift emerge?'],
    ['System Reconstruction','Welche Struktur, Zustände und Beziehungen lassen sich aus unvollständigen Spuren darstellen?','What structure, states and relationships can be represented from incomplete traces?'],
    ['Evidence Architecture','Welche Herkunft und welcher Evidenzstatus tragen jeden Claim?','What provenance and evidence status support each claim?'],
    ['Adversarial Systems Thinking','Welche Annahmen, Grenzen oder Alternativerklärungen müssen geprüft werden?','Which assumptions, boundaries or alternative explanations must be tested?'],
  ].map(([name,d,e])=><article key={name}><h3>{name}</h3><Disclosure summary={tx('Analytische Frage','Analytical question')}><p>{tx(d,e)}</p></Disclosure></article>)}</div></section>

  const Lab = () => <><PageHero eyebrow="INSTITUTION" title="Emergent Interaction Lab" body={tx('Unabhängiges, founder-led Forschungslabor für Verhalten, Interaktion und Veränderung komplexer Systeme.', 'Independent founder-led research lab for behavior, interaction and change in complex systems.')} /><section className="eil-two-col"><article><Status>MISSION</Status><h2>{tx('Verhalten, Interaktion und Veränderung belastbar untersuchen.', 'Investigating behavior, interaction and change with defensible evidence.')}</h2><p>{tx('Das Lab untersucht komplexe Systeme dort, wo Verhalten, Interaktion und Evidenz mehr zeigen als formale Beschreibung allein.', 'The Lab investigates complex systems where behavior, interaction and evidence reveal more than formal description alone.')}</p></article><article><Status>FOUNDER</Status><h2>Laura</h2><p>{tx('Gründerin · Research Lead · Methodenentwicklerin · Research Architect', 'Founder · Research Lead · Method Developer · Research Architect')}</p></article></section><LabConvergence/><section className="eil-section"><div className="eil-section-head"><Status>INSTITUTIONAL MODEL</Status><h2>{tx('Wer trägt welchen Anteil?', 'Who contributes what?')}</h2></div><div className="eil-role-grid"><article><h3>Emergent Interaction Lab</h3><p>{tx('Forschungsfragen · Programme · Methoden · Analyse · Publikationen', 'Research questions · programs · methods · analysis · publications')}</p></article><article><h3>Laura</h3><p>{tx('Forschungsleitung · Methodenentwicklung · Framework-Design · Forschungsarchitektur', 'Research direction · method development · framework design · research architecture')}</p></article><article><h3>RFI-IRFOS</h3><p>{tx('Engineering · Software · Runtime und Deployment · technische Infrastruktur · autonome Systeme · Security-Infrastruktur · technische Architektur · operative Plattformen · Produktentwicklung – nur bei ausdrücklich ausgewiesener Zusammenarbeit', 'Engineering · software · runtime and deployment · technical infrastructure · autonomous systems · security infrastructure · technical architecture · operational platforms · product development—only where explicitly attributed')}</p></article></div></section><section className="eil-principles"><h2>{tx('Research Principles', 'Research principles')}</h2>{['Evidence before narrative','Observation is not explanation','Reported state is not observed state','Unknowns remain explicit','Prediction is not certainty','Contradictions are information','Correlation is not causality','Stronger claims require stronger evidence'].map(x=><span key={x}>{x}</span>)}</section></>

  const Research = () => <><PageHero eyebrow="RESEARCH" title={tx('Forschung', 'Research')} body={tx('Research Domains ordnen das Feld; Perspektiven zeigen, wie unterschiedliche Fragen am selben Untersuchungsobjekt bearbeitet werden.', 'Research Domains organize the field; perspectives show how different questions are addressed around the same research object.')} /><Domains/><ObjectsAndPerspectives/><section className="eil-question-section"><Status>CURRENT RESEARCH QUESTIONS</Status><h2>{tx('Fragen, nicht Werbeclaims.', 'Questions, not marketing claims.')}</h2>{[
    tx('Wie verändern sich komplexe Systeme durch wiederholte Interaktion?','How do complex systems change through repeated interaction?'),
    tx('Wie verändert Interface-Darstellung, was Menschen wahrnehmen und entscheiden können?','How does interface representation change what people can perceive and decide?'),
    tx('Wann erzeugt Koordination spezialisierter Agenten Systemverhalten, das sich nicht auf Einzelrollen reduzieren lässt?','When does coordination among specialized agents produce system-level behavior not reducible to individual roles?'),
    tx('Welche Struktur lässt sich aus fragmentierter Evidenz rekonstruieren?','What structure can be reconstructed from fragmented evidence?'),
    tx('Wie lassen sich Unsicherheit, Provenienz und Widerspruch darstellen, ohne sie in einem Confidence Score aufzulösen?','How should uncertainty, provenance and contradiction be represented without collapsing them into one confidence score?'),
    tx('Wann wird Drift zu struktureller Veränderung?','When does drift become structural change?'),
    tx('Welche impliziten Constraints werden erst im Fehlerzustand sichtbar?','Which implicit constraints become visible only under failure?'),
    tx('Wann rechtfertigt longitudinale Evidenz eine Vorhersage – und wann nur Korrelation?','When does longitudinal evidence justify prediction—and when only correlation?'),
    tx('Wie verändern sich Rollen und Interaktionsmuster unter anhaltender Mensch–KI-Interaktion?','How do roles and interaction patterns change under sustained human–AI interaction?'),
    tx('Wann ist ein Muster stabil genug, um operationalisiert zu werden?','When is a pattern stable enough to operationalize?'),
  ].map((q,i)=><article key={q}><span>{String(i+1).padStart(2,'0')}</span><p>{q}</p></article>)}</section></>

  const Methods = () => <><PageHero eyebrow="METHODOLOGY" title="EIL Research Cycle" body={tx('Eine übergeordnete epistemische Forschungslogik – nicht ein einzelnes Framework.', 'A master epistemic research logic—not a single framework.')} /><section className="eil-section"><div className="eil-method-grid">{methodStages.map(([en,deName,qDe,qEn],i)=><article key={en}><span>{String(i+1).padStart(2,'0')}</span><h3>{de ? deName : en}</h3><p>{tx(qDe,qEn)}</p></article>)}</div></section><section className="eil-callout"><Status>SPECIFIC WORKFLOW</Status><h2>Emergent Interaction Loop</h2><p>Interact → Retrieve → Surface → Validate → Feed back</p><small>{tx('Bewahrt als spezifischer longitudinaler Workflow innerhalb des EIL Research Cycle.', 'Preserved as a specific longitudinal workflow within the EIL Research Cycle.')}</small></section><section className="eil-section"><div className="eil-section-head"><Status>CORE ANALYTICAL METHODS</Status><h2>{tx('Prüfbare Operationen', 'Inspectable operations')}</h2></div><div className="eil-method-detail-list">{analyticalMethods.map(m=><article key={m.name}><Status>{m.type}</Status><h2>{m.name}</h2><p>{tx(m.purpose[0],m.purpose[1])}</p><dl><dt>Input</dt><dd>{m.input}</dd><dt>Operation</dt><dd>{m.operation}</dd><dt>Output</dt><dd>{m.output}</dd><dt>Validation</dt><dd>{m.validation}</dd><dt>Limits</dt><dd>{tx(m.limits[0],m.limits[1])}</dd></dl></article>)}</div></section><section className="eil-frameworks"><Status>FRAMEWORKS · FORMALIZED</Status><h2>{tx('Framework-Familie', 'Framework family')}</h2><p>{tx('Frameworks werden nicht mit Methoden, Metriken oder Infrastruktur gleichgesetzt. Detailversionen und Publikationsbezüge werden ergänzt, sobald sie dokumentarisch verifiziert sind.', 'Frameworks are not conflated with methods, metrics or infrastructure. Detailed versions and publication links are added only once documentarily verified.')}</p><div>{frameworks.map(f=><span key={f}>{f}</span>)}</div></section></>

  const Systems = () => <><PageHero eyebrow="COMPUTATIONAL RESEARCH" title={tx('Systeme & Infrastruktur', 'Systems & infrastructure')} body={tx('Keine Gadget-Show: Jedes System wird über seine Forschungsfunktion eingeordnet.', 'Not a gadget showcase: every system is classified by its research function.')} /><AgentEnvironment /><section className="eil-section"><div className="eil-system-grid">{systems.map(([name,d,e,researchDe,researchEn])=><article className="eil-card" key={name}><Status>RESEARCH SYSTEM</Status><h2>{name}</h2><p>{tx(d,e)}</p><Disclosure summary={tx('Forschungszweck','Research purpose')}><dl><dt>Research purpose</dt><dd>{tx(researchDe,researchEn)}</dd></dl></Disclosure></article>)}</div></section></>

  const Publications = () => <><PageHero eyebrow="RESEARCH OUTPUTS" title={tx('Publikationen', 'Publications')} body={tx('Jede Veröffentlichung führt ihren eigenen Status, ihre Version und Attribution.', 'Every publication carries its own status, version and attribution.')} /><section className="eil-section"><div className="eil-publication-list">{(content.papers?.items ?? []).map((p,i)=><article key={p.id}><div><Status>{p.type.toUpperCase()}</Status><span className="eil-index">{String(i+1).padStart(2,'0')}</span></div><h2>{p.title}</h2><div className="eil-pub-meta"><span>Authors: {p.authors.join(', ')}</span><span>Date: {p.date}</span><span>Version: {p.version}</span><span>Status: {p.status}</span><span>Peer review: {p.peerReviewStatus}</span><span>Pages: {p.pages}</span>{p.repository&&<span>Repository: {p.repository}</span>}</div><Disclosure summary={tx('Abstract und Links','Abstract and links')}><p>{p.description}</p><div className="eil-pub-actions">{p.doi&&<a href={p.doi}>DOI →</a>}<a href={`${BASE}${p.file}`}>{tx('Dokument öffnen','Open document')} →</a></div></Disclosure></article>)}</div></section></>

  const Observatory = () => <><PageHero eyebrow="RESEARCH INSTRUMENT" title="Observatory" body={tx('Longitudinales Instrument für Interaktionsmuster, Drift, Rollenstabilität und Zustandsveränderung.', 'A longitudinal instrument for interaction patterns, drift, role stability and state change.')} /><section className="eil-two-col"><article><Status>SCOPE</Status><h2>{tx('Forschung sichtbar machen', 'Making research observable')}</h2><p>{tx('Das Observatory ordnet technische Signale der Forschungsfrage unter. Es ist Instrument, nicht Identität des Labs.', 'The Observatory subordinates technical signals to the research question. It is an instrument, not the Lab’s identity.')}</p></article><article><Status>CLAIM BOUNDARY</Status><h2>{tx('Beobachtung ist keine Erklärung.', 'Observation is not explanation.')}</h2><p>{tx('Sichtbare Muster begründen weder Absicht noch Kausalität. Jeder Claim bleibt an Evidenzstatus und Provenienz gebunden.', 'Visible patterns establish neither intention nor causality. Every claim remains bound to evidence status and provenance.')}</p></article></section></>

  const Notes = () => <><PageHero eyebrow="PUBLIC RESEARCH COMMUNICATION" title="Research Notes" body={tx('Lab Notes, Research Notes, Case Studies, Methods und Commentary – klar voneinander unterschieden.', 'Lab notes, research notes, case studies, methods and commentary—clearly distinguished.')} /><section className="eil-section"><div className="eil-notes-grid">{(content.news?.items ?? []).map(n=><article className="eil-card" key={n.id}><Status>RESEARCH NOTE · PRELIMINARY</Status><time>{n.date}</time><h3>{n.title}</h3><p>{n.body.replace(/<[^>]+>/g,'').slice(0,220)}…</p></article>)}</div></section></>

  const Applied = () => <><PageHero eyebrow="APPLIED RESEARCH" title="Applied Research" body={tx('Ausgewählte Methoden können auf externe Systeme, Organisationen und komplexe Fälle angewendet werden.', 'Selected methods can be applied to external systems, organizations and complex cases.')} /><section className="eil-section"><div className="eil-section-head"><Status>TRANSPARENT SCOPES</Status><h2>{tx('Research Engagements', 'Research engagements')}</h2><p>{tx('Preise bleiben sichtbar, bestimmen aber nicht die institutionelle Hierarchie.', 'Prices remain visible without defining the institutional hierarchy.')}</p></div><div className="eil-engagement-list">{engagements.map(([category,name,price,d,e])=><article key={name}><div><Status>{category.toUpperCase()}</Status><strong>{price}</strong></div><h2>{name}</h2><p>{tx(d,e)}</p><dl><dt>Deliverable</dt><dd>{tx('schriftlich definierter Scope und Ergebnisartefakt','written scope and output artifact')}</dd><dt>Research</dt><dd>Laura / Emergent Interaction Lab</dd>{category==='Implementation'&&<><dt>Engineering</dt><dd>RFI-IRFOS</dd></>}</dl><a href={`${href('home')}#contact`}>{tx('Scope prüfen', 'Discuss scope')} →</a></article>)}</div></section><section className="eil-callout"><h2>{tx('Research ist nicht Engineering.', 'Research is not engineering.')}</h2><p>{tx('Wo technische Umsetzung erforderlich ist, wird RFI-IRFOS separat als Engineering-Partner ausgewiesen.', 'Where implementation is required, RFI-IRFOS is credited separately as the engineering partner.')}</p></section></>

  const MethodLibrary = () => <section className="eil-section"><div className="eil-section-head"><Status>METHOD LIBRARY</Status><h2>{tx('Formalisierte Methoden & Instrumente', 'Formalized methods & instruments')}</h2><p>{tx('Status beschreibt die öffentlich belegbare Reife – nicht eine behauptete externe Validierung.', 'Status describes publicly evidenced maturity—not claimed external validation.')}</p></div><div className="eil-library-grid">{methodLibrary.map(([name,status,full,unit,evidence,output,domain])=><article key={name}><Status>{status}</Status><h2>{name}</h2><p>{full}</p><dl><dt>Unit of analysis</dt><dd>{unit}</dd><dt>Required evidence</dt><dd>{evidence}</dd><dt>Output</dt><dd>{output}</dd><dt>Domain</dt><dd>{domain}</dd><dt>Version</dt><dd>{tx('nicht öffentlich verifiziert','not publicly verified')}</dd></dl></article>)}</div></section>

  const SystemArchitecture = () => <section className="eil-system-architecture"><div className="eil-section-head"><Status>SYSTEM TAXONOMY</Status><h2>{tx('Forschungsfunktion vor Produktname', 'Research function before product name')}</h2></div><div><article><small>RESEARCH INSTRUMENTS</small><strong>Observatory · CEI · interaction analysis tooling</strong></article><article><small>INFRASTRUCTURE</small><strong>Research Knowledge Graph · EIL World Model · provenance layer · research corpus</strong></article><article><small>AUTONOMOUS SYSTEMS</small><strong>Multi-Agent Research Environment (lauras-team) · Jarvis</strong></article><article><small>ANALYTICAL SYSTEMS</small><strong>Call Laura</strong></article></div><p>{tx('Für jedes System gelten: Zweck, unterstützte Forschungsfrage, Status, Inputs, Outputs, Evidenzgrenzen, Ownership und zugehörige Publikationen.', 'Every system is governed by purpose, supported research question, status, inputs, outputs, evidence boundaries, ownership and related publications.')}</p></section>

  const SystemRecords = () => <section className="eil-section"><div className="eil-section-head"><Status>RESEARCH RECORDS</Status><h2>{tx('Was jedes System untersuchbar macht', 'What each system makes investigable')}</h2></div><div className="eil-library-grid">{systemDetails.map(([name,qDe,qEn,inputDe,inputEn,outputDe,outputEn])=><article key={name}><Status>RESEARCH SYSTEM</Status><h2>{name}</h2><p>{tx(qDe,qEn)}</p><Disclosure summary={tx('Input, Output und Evidenzgrenze', 'Input, output and evidence boundary')}><dl><dt>Input</dt><dd>{tx(inputDe,inputEn)}</dd><dt>Output</dt><dd>{tx(outputDe,outputEn)}</dd><dt>Evidence boundary</dt><dd>{tx('Nur aus erfassten oder explizit abgeleiteten Signalen.','Captured or explicitly derived signals only.')}</dd></dl></Disclosure></article>)}</div></section>

  const KnowledgeModelDistinction = () => <section className="eil-two-col"><article><Status>RESEARCH KNOWLEDGE GRAPH</Status><h2>{tx('Wie hängt das zusammen, was wir wissen?', 'How are the things we know connected?')}</h2><p>{tx('Der Graph verbindet Evidenz, Quellen, Entitäten, Ereignisse, Claims und Beziehungen, ohne ihren Ursprung zu verwischen.', 'The graph connects evidence, sources, entities, events, claims and relationships without obscuring provenance.')}</p></article><article><Status>EIL WORLD MODEL</Status><h2>{tx('Welche Zustandsdarstellung trägt die aktuelle Evidenz?', 'What representation of state is supported by current evidence?')}</h2><p>{tx('Das World Model repräsentiert Systemzustand, Veränderungen, alternative Zustände oder Hypothesen und die verbleibende Unsicherheit.', 'The World Model represents system state, changes, alternative states or hypotheses and remaining uncertainty.')}</p></article></section>

  const ObservatoryModel = () => <section className="eil-section"><div className="eil-section-head"><Status>OBSERVATION MODEL</Status><h2>Corpus → Extraction → State → Comparison → Metrics → Visualization</h2></div><div className="eil-observatory-grid">{[
    [tx('Interaktionsdynamik','Interaction dynamics'),tx('Wie verändern sich Muster durch wiederholte Interaktion?','How do patterns change through repeated interaction?')],
    [tx('Semantischer Drift','Semantic drift'),tx('Wie verschieben sich Bedeutungen, Begriffe und Referenzen über Zeit?','How do meanings, terms and references shift over time?')],
    [tx('Rollenstabilität','Role stability'),tx('Welche Rollen bleiben stabil, welche verändern sich?','Which roles remain stable and which change?')],
    [tx('Zustandsübergänge','State transitions'),tx('Welche beobachtbaren Ereignisse markieren Zustandswechsel?','Which observable events mark state changes?')],
    [tx('Widersprüche','Contradictions'),tx('Wo weichen Darstellung, Erwartung und Beobachtung voneinander ab?','Where do representation, expectation and observation diverge?')],
    [tx('Kontextakkumulation','Context accumulation'),tx('Welche Vorgeschichte verändert die Interpretation eines späteren Signals?','Which history changes the interpretation of a later signal?')],
    [tx('Evidenzmodell','Evidence model'),'observed · reported · derived · inferred · hypothesized · unknown'],
    [tx('Claim-Grenzen','Claim boundaries'),tx('Observation ist keine Erklärung. Keine Absichtsinferenz aus Verhaltensspuren; Korrelation ist keine Kausalität.','Observation is not explanation. No inference of intention from behavioral traces; correlation is not causation.')],
  ].map(([name,detail])=><article key={name}><h3>{name}</h3><Disclosure summary={tx('Details anzeigen','Show details')}><p>{detail}</p></Disclosure></article>)}</div></section>

  const ObservatoryPreview = () => <section className="eil-section"><div className="eil-section-head"><Status>RESEARCH VIEW PREVIEW</Status><h2>{tx('Welche Forschungsansichten das Instrument verbindet', 'Research views connected by the instrument')}</h2><p>{tx('Vier sichtbare Gruppen halten die Architektur verständlich; die einzelnen Views bleiben einklappbar.', 'Four visible groups keep the architecture legible; individual views remain available on demand.')}</p></div><div className="eil-observatory-grid eil-observatory-groups">{observatoryPreviewGroups.map(([group,views])=><article key={group}><Status>{group}</Status><Disclosure summary={tx('Ansichten anzeigen','Show views')}>{views.map(([name,d,e])=><div className="eil-preview-detail" key={name}><h3>{name}</h3><p>{tx(d,e)}</p></div>)}</Disclosure></article>)}</div></section>

  const PublicationArchitecture = () => <section className="eil-output-strip"><Status>OUTPUT TAXONOMY</Status><h2>{tx('Publikationsstatus bleibt explizit.', 'Publication status remains explicit.')}</h2><div>{['Peer-reviewed (if applicable)','Preprints','Research reports','Methods papers','Technical reports','Datasets','Research notes','Working papers'].map(x=><span key={x}>{x}</span>)}</div></section>

  const EngagementProcess = () => <section className="eil-section"><div className="eil-section-head"><Status>ENGAGEMENT PROCESS</Status><h2>{tx('Vom Scope zum Ergebnisartefakt', 'From scope to output artifact')}</h2><p>{tx('Finale Preise hängen von Evidenzvolumen, Systemgrenze und Komplexität ab.', 'Final pricing depends on evidence volume, system boundary and complexity.')}</p></div><div className="eil-process">{['Scope','Evidence','Investigation','Reconstruction / Analysis','Deliverable','Optional Engineering'].map((x,i)=><article key={x}><span>{String(i+1).padStart(2,'0')}</span><strong>{x}</strong></article>)}</div></section>

  const MethodsPublic = () => <><PageHero eyebrow="PUBLIC METHODOLOGY" title={tx('Methoden & Fähigkeiten','Methods & capabilities')} body={tx('Öffentlich beschreibbare Forschungsprinzipien und methodische Fähigkeiten. Interne Operationalisierung bleibt geschützt.', 'Publicly describable research principles and methodological capabilities. Internal operationalization remains protected.')} /><section className="eil-principles"><h2>{tx('Öffentliche Forschungslogik','Public research logic')}</h2>{['Observe','Attribute','Separate','Contextualize','Reconstruct','Challenge','Model','Validate'].map((x,i)=><span key={x}><b>{String(i+1).padStart(2,'0')}</b>{x}</span>)}</section><section className="eil-callout eil-transition-rule"><Status>SIMPLIFIED PUBLIC RESEARCH LOGIC</Status><h2>{tx('Jeder Übergang erhält Herkunft, Evidenzstatus und Unsicherheit.','Every transition preserves provenance, evidence status and uncertainty.')}</h2><small>{tx('Didaktische öffentliche Darstellung – keine Implementierungsspezifikation.','Didactic public representation—not an implementation specification.')}</small></section><section className="eil-section"><div className="eil-section-head"><Status>PUBLIC CAPABILITY LAYER</Status><h2>{tx('Was das Lab methodisch leisten kann','What the Lab can do methodologically')}</h2><p>{tx('Die Website beschreibt Forschungszweck und Ergebnisraum – nicht interne Inferenz-, Scoring-, Orchestrierungs- oder State-Machine-Mechanik.','The website describes research purpose and output space—not internal inference, scoring, orchestration or state-machine mechanics.')}</p></div><div className="eil-program-grid">{publicCapabilities.map(([name,status,d,e])=><article className="eil-card" key={name}><Status>{status}</Status><h3>{name}</h3><p>{tx(d,e)}</p>{name==='HMI Analysis'&&<Disclosure summary={tx('HMI-Schwerpunkte','HMI scope')}><p>{tx('Interface · Wahrnehmung · Informationsdarstellung · Mental Models · Sichtbarkeit von Systemzuständen · Informationsverlust · Entscheidungsunterstützung · Adaptation','Interface · perception · information representation · mental models · system-state visibility · information loss · decision support · adaptation')}</p></Disclosure>}</article>)}</div></section><section className="eil-section"><div className="eil-section-head"><Status>ANALYTICAL METHODS</Status><h2>{tx('Öffentlich beschreibbare analytische Operationen','Publicly describable analytical operations')}</h2></div><div className="eil-library-grid">{analyticalMethods.map(method=><article key={method.name}><Status>{method.type}</Status><h2>{method.name}</h2><p>{tx(method.purpose[0],method.purpose[1])}</p><Disclosure summary={tx('Input, Operation, Output, Validierung und Grenzen','Input, operation, output, validation and limits')}><dl><dt>Input</dt><dd>{method.input}</dd><dt>Operation</dt><dd>{method.operation}</dd><dt>Output</dt><dd>{method.output}</dd><dt>Validation</dt><dd>{method.validation}</dd><dt>Limits</dt><dd>{tx(method.limits[0],method.limits[1])}</dd></dl></Disclosure></article>)}</div></section><section className="eil-frameworks"><Status>FRAMEWORKS</Status><h2>{tx('Frameworks bleiben von Methoden, Metriken und Infrastruktur getrennt.','Frameworks remain distinct from methods, metrics and infrastructure.')}</h2><p>{tx('Öffentlich benannte Framework-Familien werden ohne erfundene Reife- oder Validierungsclaims gezeigt.','Publicly named framework families are shown without inferred maturity or validation claims.')}</p><div>{frameworks.map(name=><span key={name}>{name}</span>)}</div></section><EvidenceModel/></>

  const AppliedPublic = () => <><PageHero eyebrow="APPLIED RESEARCH" title="Applied Research" body={tx('Ausgewählte EIL-Fähigkeiten können auf klar begrenzte externe Untersuchungen angewendet werden – mit expliziten Evidenzgrenzen und unveränderten, verifizierten Preisen.', 'Selected EIL capabilities can be applied to clearly bounded external investigations—with explicit evidence boundaries and unchanged verified prices.')} /><section className="eil-section"><div className="eil-section-head"><Status>CAPABILITIES</Status><h2>{tx('Was untersucht werden kann','What can be investigated')}</h2><p>{tx('Capabilities sind keine Pakete und bestimmen nicht automatisch ein Engagement Level.', 'Capabilities are not packages and do not automatically determine an engagement level.')}</p></div><div className="eil-program-grid">{appliedCapabilities.map(([name,d,e])=><article className="eil-card" key={name}><h3>{name}</h3><p>{tx(d,e)}</p></article>)}</div></section><section className="eil-section"><div className="eil-section-head"><Status>ENGAGEMENT LEVELS</Status><h2>ASSESS · INVESTIGATE · BUILD · MONITOR</h2><p>{tx('Die Level beschreiben unterschiedliche Formen und Tiefen eines Engagements.', 'The levels describe different forms and depths of engagement.')}</p></div><div className="eil-process">{engagementLevels.map(([level,d,e],i)=><article key={level}><span>{String(i+1).padStart(2,'0')}</span><strong>{level}</strong><p>{tx(d,e)}</p></article>)}</div></section><EngagementProcess/><section className="eil-section"><div className="eil-section-head"><Status>VERIFIED EXISTING OFFERS</Status><h2>{tx('Bestehende Angebote & Preise','Existing offers and prices')}</h2><p>{tx('Bestehende Namen, Beschreibungen und Preise bleiben von der Engagement-Level-Taxonomie getrennt.', 'Existing names, descriptions and prices remain separate from the engagement-level taxonomy.')}</p></div><div className="eil-engagement-list">{engagements.map(([,name,price,d,e])=><article key={name}><div><Status>EXISTING OFFER</Status><strong>{price}</strong></div><h2>{name}</h2><p>{tx(d,e)}</p><Disclosure summary={tx('Scope-Abgrenzung','Scope boundary')}><p>{tx('Der konkrete Untersuchungsumfang und das primäre Ergebnisartefakt werden im vereinbarten Scope festgelegt.','The concrete investigation scope and primary output artifact are defined in the agreed scope.')}</p></Disclosure><a href={`${href('home')}#contact`}>{tx('Research Engagement anfragen','Request research engagement')} →</a></article>)}</div></section><section className="eil-attribution-note"><h2>{tx('Capabilities, Engagement Levels und Angebote bleiben getrennt.','Capabilities, engagement levels and offers remain distinct.')}</h2><p>{tx('EIL verantwortet Forschung. Technische Umsetzung durch RFI-IRFOS wird nur bei tatsächlicher Zusammenarbeit separat attribuiert.','EIL owns the research. Technical implementation by RFI-IRFOS is attributed separately only where collaboration actually occurs.')}</p></section></>

  // Legacy page bodies remain temporarily available for content comparison
  // during the beta, but are intentionally not exposed as public routes.
  void Methods
  void Applied
  void MethodLibrary

  const LabLineage = () => <section className="eil-spine"><Status>RESEARCH LINEAGE</Status><h2>{tx('Von wiederkehrenden Forschungsanforderungen zu persistenter Forschungsinfrastruktur.', 'From recurring research requirements to persistent research infrastructure.')}</h2><p>{tx('Menschliche analytische Praxis und wiederkehrende Forschungsanforderungen machten wiederholbare Operationen sichtbar. Daraus entstanden Methoden und Protokolle, spezialisierte Rollen, computational Research Infrastructure, persistenter Forschungszustand und longitudinale Beobachtung. Longitudinale Mensch–KI-Forschung war ein wichtiger historischer Ausgangspunkt – die Darstellung ist eine vereinfachte konzeptionelle Lineage, keine strikt lineare Chronologie.', 'Human analytical practice and recurring research requirements exposed repeatable operations. These developed into methods and protocols, specialized roles, computational research infrastructure, persistent research state and longitudinal observation. Longitudinal human–AI research was an important historical starting point—the representation is a simplified conceptual lineage, not a strictly linear chronology.')}</p><p className="eil-lineage-distinction">{tx('EIL nutzt nicht nur computational Tools zur Unterstützung von Forschung. Teile der analytischen Praxis werden schrittweise in überprüfbare computational Research Systems formalisiert.', 'EIL does not only use computational tools to support research. Parts of its analytical practice are progressively formalized into inspectable computational research systems.')}</p></section>

  const LabDeep = () => <><Lab/><LabLineage/><EvidenceModel/></>
  const ResearchDeep = () => <><Research/><ResearchMap/></>
  const SystemsDeep = () => <><Systems/><ResearchEnvironmentOverview/><KnowledgeModelDistinction/><SystemArchitecture/><SystemRecords/></>
  const PublicationsDeep = () => <><Publications/><PublicationArchitecture/></>
  const ObservatoryDeep = () => <><Observatory/><ObservatoryModel/><ObservatoryPreview/></>

  const pages: Record<InstitutionalRoute, () => ReactElement> = { home: Home, lab: LabDeep, research: ResearchDeep, methods: MethodsPublic, systems: SystemsDeep, publications: PublicationsDeep, observatory: ObservatoryDeep, notes: Notes, 'applied-research': AppliedPublic }
  const Page = pages[route]
  return <div className="eil-site" data-theme={theme}><Header/><main className="eil-main"><Page/></main><Footer/></div>
}
